'use strict';
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const PORT = parseInt(process.env.PORT || '8080', 10);
const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
const DATA_FILE = path.join(DATA_DIR, 'items.json');
const PUBLIC_DIR = path.join(__dirname, 'public');

fs.mkdirSync(DATA_DIR, { recursive: true });

// ---- durable storage -------------------------------------------------------
// Items: { id, text, bought, createdAt, updatedAt }
let items = [];
let rev = 0;
const deleted = {}; // id -> deletedAt (tombstones so the UI can drop items)

function load() {
  try {
    const raw = JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
    items = Array.isArray(raw.items) ? raw.items : [];
    rev = raw.rev || 0;
    Object.assign(deleted, raw.deleted || {});
  } catch (e) {
    if (e.code !== 'ENOENT') console.error('load failed:', e.message);
    items = [];
    rev = 0;
  }
}
let saveTimer = null;
function persistSync() {
  const tmp = DATA_FILE + '.tmp';
  const data = JSON.stringify({ rev, items, deleted });
  fs.writeFileSync(tmp, data);
  fs.renameSync(tmp, DATA_FILE);
}
function persist() {
  if (saveTimer) return;
  saveTimer = setTimeout(() => {
    saveTimer = null;
    try { persistSync(); } catch (e) { console.error('save failed:', e.message); }
  }, 20);
}
load();

// ---- helpers ---------------------------------------------------------------
function newId() { return crypto.randomBytes(8).toString('hex'); }
function snapshot() { return { rev, items: items.map((i) => ({ ...i })) }; }

function json(res, code, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(code, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (c) => {
      data += c;
      if (data.length > 1e6) { reject(new Error('too large')); req.destroy(); }
    });
    req.on('end', () => {
      if (!data) return resolve({});
      try { resolve(JSON.parse(data)); } catch (e) { reject(new Error('bad json')); }
    });
    req.on('error', reject);
  });
}

function findItem(id) { return items.find((i) => i.id === id); }

// operations: shared by HTTP API and the internal sync feed
function opAdd(text) {
  const t = String(text || '').trim();
  if (!t) return { error: 'text required' };
  if (t.length > 500) return { error: 'text too long' };
  const now = Date.now();
  const item = { id: newId(), text: t, bought: false, createdAt: now, updatedAt: now };
  items.push(item);
  rev++;
  persist();
  return { item, rev };
}

function opSetBought(id, bought) {
  const it = findItem(id);
  if (!it) return { error: 'not found', code: 404 };
  it.bought = !!bought;
  it.updatedAt = Date.now();
  rev++;
  persist();
  return { item: { ...it }, rev };
}

function opToggle(id) {
  const it = findItem(id);
  if (!it) return { error: 'not found', code: 404 };
  return opSetBought(id, !it.bought);
}

function opDelete(id) {
  const idx = items.findIndex((i) => i.id === id);
  if (idx < 0) return { error: 'not found', code: 404 };
  items.splice(idx, 1);
  deleted[id] = Date.now();
  rev++;
  persist();
  return { ok: true, rev };
}

function opClearBought() {
  const keep = [];
  for (const it of items) {
    if (it.bought) deleted[it.id] = Date.now();
    else keep.push(it);
  }
  items = keep;
  rev++;
  persist();
  return { ok: true, rev };
}

// ---- static files ----------------------------------------------------------
const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.json': 'application/json; charset=utf-8',
};

function serveStatic(req, res, pathname) {
  let rel = pathname === '/' ? '/index.html' : pathname;
  rel = decodeURIComponent(rel);
  const filePath = path.normalize(path.join(PUBLIC_DIR, rel));
  if (!filePath.startsWith(PUBLIC_DIR)) { json(res, 403, { error: 'forbidden' }); return; }
  fs.readFile(filePath, (err, buf) => {
    if (err) {
      // SPA-ish fallback for unknown non-API paths
      if (path.extname(rel) === '') return serveStatic(req, res, '/index.html');
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('not found');
      return;
    }
    res.writeHead(200, {
      'Content-Type': MIME[path.extname(filePath)] || 'application/octet-stream',
      'Cache-Control': 'no-cache',
    });
    res.end(buf);
  });
}

// ---- server ----------------------------------------------------------------
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const p = url.pathname;
  const m = req.method;

  try {
    if (p === '/api/health' || p === '/healthz') {
      return json(res, 200, { ok: true, rev, count: items.length });
    }

    if (p === '/api/items' && m === 'GET') {
      return json(res, 200, snapshot());
    }

    if (p === '/api/items' && m === 'POST') {
      const body = await readBody(req);
      const r = opAdd(body.text || body.item);
      if (r.error) return json(res, 400, r);
      return json(res, 201, r);
    }

    if (p === '/api/state' && m === 'GET') {
      return json(res, 200, snapshot());
    }

    // /api/items/:id  (PATCH {bought}, PUT, DELETE)
    let mm = p.match(/^\/api\/items\/([^/]+)$/);
    if (mm) {
      const id = mm[1];
      if (m === 'PATCH' || m === 'PUT' || m === 'POST') {
        const body = await readBody(req);
        let r;
        if (Object.prototype.hasOwnProperty.call(body, 'bought')) r = opSetBought(id, body.bought);
        else if (body.toggle) r = opToggle(id);
        else if (typeof body.text === 'string') {
          const it = findItem(id);
          if (!it) r = { error: 'not found', code: 404 };
          else { it.text = body.text.trim() || it.text; it.updatedAt = Date.now(); rev++; persist(); r = { item: { ...it }, rev }; }
        } else r = { error: 'nothing to update' };
        return json(res, r.error ? (r.code || 400) : 200, r);
      }
      if (m === 'DELETE') {
        const r = opDelete(id);
        return json(res, r.error ? r.code : 200, r);
      }
    }

    if (p === '/api/items' && m === 'DELETE') {
      return json(res, 200, opClearBought());
    }

    // ---- internal, server-to-server sync feed (shared network) ----
    if (p === '/api/sync' && m === 'GET') {
      return json(res, 200, { source: 'repo-a', ...snapshot() });
    }
    if (p === '/api/sync' && m === 'POST') {
      const body = await readBody(req);
      const out = [];
      for (const op of Array.isArray(body.ops) ? body.ops : []) {
        try {
          if (op.op === 'add' && op.text) out.push(opAdd(op.text));
          else if (op.op === 'set' && op.id) out.push(opSetBought(op.id, op.bought));
          else if (op.op === 'del' && op.id) out.push(opDelete(op.id));
        } catch (e) { out.push({ error: e.message }); }
      }
      return json(res, 200, { ok: true, rev, results: out, ...snapshot() });
    }

    if (p.startsWith('/api/')) return json(res, 404, { error: 'no such endpoint' });

    if (m === 'GET' || m === 'HEAD') return serveStatic(req, res, p);
    return json(res, 405, { error: 'method not allowed' });
  } catch (e) {
    return json(res, 400, { error: e.message });
  }
});

process.on('SIGTERM', () => { try { persistSync(); } catch (_) {} process.exit(0); });
process.on('SIGINT', () => { try { persistSync(); } catch (_) {} process.exit(0); });

server.listen(PORT, '0.0.0.0', () => {
  console.log(`shared shopping list listening on :${PORT} (data: ${DATA_FILE})`);
});
