(() => {
  'use strict';
  const POLL_MS = 1500;              // other people's changes appear within ~1.5s
  const listEl = document.getElementById('list');
  const emptyEl = document.getElementById('empty');
  const formEl = document.getElementById('add-form');
  const inputEl = document.getElementById('item');
  const statusEl = document.getElementById('status');
  const clearEl = document.getElementById('clear');

  let state = { rev: -1, items: [] };
  let pending = 0;                    // in-flight mutations; polling pauses for them
  let localEdits = new Map();         // id -> timestamp of local change (brief optimistic guard)

  function setStatus(cls, text) {
    statusEl.className = cls;
    statusEl.textContent = text;
  }

  function render() {
    const items = state.items.slice().sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
    listEl.textContent = '';
    for (const it of items) {
      const li = document.createElement('li');
      li.dataset.id = it.id;
      if (it.bought) li.classList.add('bought');

      const cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.checked = !!it.bought;
      cb.setAttribute('aria-label', 'Bought: ' + it.text);
      cb.addEventListener('change', () => { toggle(it.id, cb.checked); });

      const span = document.createElement('span');
      span.className = 'text';
      span.textContent = it.text;

      const del = document.createElement('button');
      del.type = 'button';
      del.className = 'secondary';
      del.textContent = '✕';
      del.title = 'Remove item';
      del.setAttribute('aria-label', 'Remove ' + it.text);
      del.addEventListener('click', () => { remove(it.id); });

      li.append(cb, span, del);
      listEl.append(li);
    }
    emptyEl.hidden = items.length > 0;
  }

  function merge(newState) {
    if (!newState || typeof newState.rev !== 'number') return;
    if (newState.rev < state.rev) return;
    state = newState;
    render();
  }

  async function api(method, url, body) {
    pending++;
    try {
      const res = await fetch(url, {
        method,
        headers: body ? { 'Content-Type': 'application/json' } : {},
        body: body ? JSON.stringify(body) : undefined,
        cache: 'no-store',
      });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      setStatus('live', 'live');
      return await res.json();
    } catch (e) {
      setStatus('offline', 'offline — retrying');
      throw e;
    } finally {
      pending--;
    }
  }

  async function refresh() {
    if (pending > 0) return;
    try {
      const s = await api('GET', '/api/items');
      // keep local optimistic checkbox state for a moment
      const now = Date.now();
      for (const it of s.items) {
        const t = localEdits.get(it.id);
        if (t && now - t < 1200) {
          const local = state.items.find((x) => x.id === it.id);
          if (local) it.bought = local.bought;
        }
      }
      merge(s);
      setStatus('live', 'live — synced');
    } catch (_) { /* status already set */ }
  }

  async function toggle(id, bought) {
    const local = state.items.find((x) => x.id === id);
    if (local) { local.bought = bought; localEdits.set(id, Date.now()); render(); }
    try {
      const r = await api('PATCH', '/api/items/' + encodeURIComponent(id), { bought });
      if (r && r.items) merge({ rev: r.rev, items: r.items });
    } catch (_) { /* next poll reconciles */ }
  }

  async function remove(id) {
    try {
      const r = await api('DELETE', '/api/items/' + encodeURIComponent(id));
      if (r && r.items) merge({ rev: r.rev, items: r.items });
    } catch (_) {}
  }

  formEl.addEventListener('submit', async (ev) => {
    ev.preventDefault();
    const text = inputEl.value.trim();
    if (!text) return;
    inputEl.value = '';
    try {
      const r = await api('POST', '/api/items', { text });
      if (r && r.items) merge({ rev: r.rev, items: r.items });
    } catch (_) { inputEl.value = text; }
    inputEl.focus();
  });

  clearEl.addEventListener('click', async () => {
    try {
      const r = await api('DELETE', '/api/items');
      if (r && r.items) merge({ rev: r.rev, items: r.items });
    } catch (_) {}
  });

  document.addEventListener('visibilitychange', () => { if (!document.hidden) refresh(); });
  window.addEventListener('online', refresh);

  refresh();
  setInterval(refresh, POLL_MS);
  inputEl.focus();
})();
EOF
