# repo-a has no host port: repo-b's service `app` is the single publisher of
# host port 8080 (see the coordination on the message board). This project deploys
# as a working, cooperating replica:
#   - `shopping` serves the same API/UI on the shared network (http://shopping:8080/)
#   - `proxy`   forwards http://app:8080/ (the 8080 publisher) on the shared network
#   - `shopping` has its own durable JSON volume, so it can serve the list on its
#     own if the other repo is ever absent.
services:
  shopping:
    build: .
    image: shopping-list-a:latest
    restart: unless-stopped
    expose:
      - "8080"
    environment:
      PORT: "8080"
      DATA_DIR: /data
    volumes:
      - shopping-data:/data

  proxy:
    image: node:22-alpine
    restart: unless-stopped
    expose:
      - "8080"
    environment:
      PORT: "8080"
      UPSTREAM: http://app:8080
    command: ["node", "/proxy/server.js"]
    configs:
      - source: proxy_js
        target: /proxy/server.js
    depends_on:
      - shopping

configs:
  proxy_js:
    file: ./proxy-server.js

volumes:
  shopping-data:
'use strict';
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const PORT = parseInt(process.env.PORT || '8080', 10);
const DATA_DIR = process.env.DATA_DIR || '/data';
const DATA_FILE = path.join(DATA_DIR, 'items.json');
const PUBLIC_DIR = path.join(__dirname, 'public');

fs.mkdirSync(DATA_DIR, { recursive: true });

let items = [];
let clients = new Set();

function load() {
  try {
    const raw = fs.readFileSync(DATA_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed.items)) items = parsed.items;
  } catch (e) {
    items = [];
  }
}
function save() {
  const tmp = DATA_FILE + '.tmp';
  fs.writeFileSync(tmp, JSON.stringify({ items }, null, 2));
  fs.renameSync(tmp, DATA_FILE);
}
load();

function version() {
  // simple monotonically increasing token derived from content + counter
  return ++revCounter;
}
let revCounter = Date.now();

function snapshot() {
  return { rev: revCounter, items };
}
function broadcast() {
  revCounter = Date.now() > revCounter ? Date.now() : revCounter + 1;
  const data = 'data: ' + JSON.stringify(snapshot()) + '\n\n';
  for (const res of clients) {
    try { res.write(data); } catch (e) { clients.delete(res); }
  }
}

function sendJSON(res, code, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(code, {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'Access-Control-Allow-Origin': '*'
  });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    let len = 0;
    req.on('data', (chunk) => {
      len += chunk.length;
      if (len > 1e6) { reject(new Error('too large')); req.destroy(); return; }
      data += chunk;
    });
    req.on('end', () => {
      if (!data) return resolve({});
      try { resolve(JSON.parse(data)); } catch (e) { reject(e); }
    });
    req.on('error', reject);
  });
}

